import ast
import json
from pathlib import Path
import subprocess

FIELDS = {
    'player_data': 'player_data', 'current_skill': 'current_skill',
    'answer_shown': 'answer_shown', 'card_turned': 'card_turned', 'exp_awarded': 'exp_awarded',
    '_REVIEW_UNDO_STACK': 'review_undo_stack', '_DIRECT_ACTION_UNDO_STACK': 'direct_action_undo_stack',
    '_REVIEW_FEEDBACK_CONTEXT': 'review_feedback_context',
    '_REVIEW_FEEDBACK_INITIAL_XP': 'review_feedback_initial_xp',
    '_REVIEW_FEEDBACK_FLUSHING': 'review_feedback_flushing',
    '_PENDING_BANKSTANDING_NOTICE': 'pending_bankstanding_notice',
    '_PENDING_REVIEW_DIALOGS': 'pending_review_dialogs',
    '_SKILL_AVAILABILITY_CACHE_FINGERPRINT': 'skill_availability_cache_fingerprint',
}
REVERSE = {value: key for key, value in FIELDS.items()}

class Normalize(ast.NodeTransformer):
    def visit_Global(self, node):
        node.names = [name for name in node.names if name not in FIELDS]
        return node if node.names else None

    def visit_Attribute(self, node):
        if isinstance(node.value, ast.Name) and node.value.id == '_state' and node.attr in REVERSE:
            return ast.copy_location(ast.Name(id=REVERSE[node.attr], ctx=node.ctx), node)
        if isinstance(node.value, ast.Attribute) and node.value.attr == '_state' and node.attr in REVERSE:
            return ast.copy_location(ast.Attribute(value=node.value.value, attr=REVERSE[node.attr], ctx=node.ctx), node)
        return self.generic_visit(node)

paths = ['__init__.py', *json.loads(Path('/tmp/dispatcher-state-test-files.json').read_text())]
for path in paths:
    before = ast.parse(subprocess.check_output(['git', 'show', 'HEAD:' + path], text=True))
    after = ast.parse(Path(path).read_text())
    if path == '__init__.py':
        before.body = [n for n in before.body if isinstance(n, (ast.FunctionDef, ast.ClassDef))]
        after.body = [n for n in after.body if isinstance(n, (ast.FunctionDef, ast.ClassDef))]
    normalized_before = ast.dump(Normalize().visit(before), include_attributes=False)
    normalized_after = ast.dump(Normalize().visit(after), include_attributes=False)
    if normalized_before != normalized_after:
        raise SystemExit('Unexpected AST delta: ' + path)
print(f'AST equivalence PASS: root function/class bodies and all {len(paths)-1} migrated test modules, excluding only the explicit state access and retired global declarations.')
